import * as THREE from './vendor/three.module.js';
import {buildWorld} from './world.js';
import {createCar,createPerson,createBoat,animatePerson} from './actors.js';
import {JOBS,TAPES,PAINTS,UPGRADES,ROADS,clamp,distance,angleDelta,inWater,blocked,makeRoute,freshSave,validateSave,settleJob} from './core.js';

const $=s=>document.querySelector(s),canvas=$('#scene'),STORE='beijing-nightline.v1';
let saved=freshSave(),storageAvailable=true;
try{const raw=localStorage.getItem(STORE);if(raw)saved=validateSave(JSON.parse(raw));}catch{storageAvailable=false;}
let renderer;
try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance',preserveDrawingBuffer:false});}catch(e){$('#fatal').hidden=false;$('#fatal p').textContent='浏览器无法创建WebGL场景。请启用硬件加速后用桌面版Edge或Chrome重新打开。';throw e;}
renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.15,1800);scene.fog=new THREE.FogExp2('#c0b19c',.0014);
const hemi=new THREE.HemisphereLight('#e5d9c1','#6d6950',2);scene.add(hemi);
const sun=new THREE.DirectionalLight('#ffd5a4',3);sun.position.set(-120,230,-80);sun.castShadow=true;sun.shadow.camera.left=-170;sun.shadow.camera.right=170;sun.shadow.camera.top=170;sun.shadow.camera.bottom=-170;sun.shadow.camera.far=800;sun.shadow.bias=-.0003;scene.add(sun);scene.add(sun.target);
const sky=new THREE.Mesh(new THREE.SphereGeometry(1100,32,16),new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{top:{value:new THREE.Color('#486d80')},bottom:{value:new THREE.Color('#f2b77c')}},vertexShader:'varying vec3 v;void main(){v=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 v;uniform vec3 top;uniform vec3 bottom;void main(){float h=clamp(normalize(v).y*1.5,0.,1.);gl_FragColor=vec4(mix(bottom,top,pow(h,.5)),1.);}'}));scene.add(sky);
const sunDisk=new THREE.Mesh(new THREE.SphereGeometry(14,16,10),new THREE.MeshBasicMaterial({color:'#ffe7ad',fog:false}));scene.add(sunDisk);
const world=buildWorld(scene),water=world.water;
const character=createPerson('#b75c3f');scene.add(character);
const player={x:saved.position.x,z:saved.position.z,yaw:Math.PI,speed:0,crouch:false};
if(blocked(player,world.colliders)||inWater(player,water)){player.x=-18;player.z=35;}
const vehicles=[],traffic=[];let activeVehicle=null;
function addVehicle(x,z,color,kind,name,owned=false,boat=false){const model=boat?createBoat(color):createCar(color,kind);scene.add(model);const v={id:vehicles.length,x,z,yaw:Math.PI,speed:0,boost:100,model,name,kind,owned,boat};model.position.set(x,0,z);model.rotation.y=v.yaw;vehicles.push(v);return v;}
const ownCar=addVehicle(-13,35,PAINTS[saved.paint].value,'sedan','京城 GT',true);
addVehicle(10,-36,'#d3a33c','taxi','京城出租');addVehicle(210,-92,'#ab4230','sport','赤影 RS');addVehicle(-210,104,'#cabd9a','van','街坊速递');
const boat=addVehicle(-225,-292,'#d26243','boat','什海游船',false,true);
const policeCars=[addVehicle(390,150,'#e0e5df','police','城市巡逻'),addVehicle(-390,-150,'#d7e1db','police','街区巡逻')];
for(let i=0;i<10;i++){const cx=[-300,-100,100,300][i%4],cz=[-100,100][Math.floor(i/4)%2];const v=addVehicle(cx-95,cz-95,['#608078','#bbb4a1','#9b4237','#565b68','#c9a344'][i%5],i%4===0?'taxi':'sedan','街头车辆');v.path=[{x:cx-95,z:cz-95},{x:cx+95,z:cz-95},{x:cx+95,z:cz+95},{x:cx-95,z:cz+95}];v.next=i%4;v.x=v.path[v.next].x;v.z=v.path[v.next].z;v.next=(v.next+1)%4;v.cruise=9+i%4;traffic.push(v);}
const pedestrians=[];
for(let i=0;i<14;i++){const cx=[-100,100,300][i%3],cz=[-100,100][i%2],model=createPerson(['#7a8570','#c27d45','#4c6b79','#916657'][i%4]);const path=[{x:cx-82,z:cz-82},{x:cx+82,z:cz-82},{x:cx+82,z:cz+82},{x:cx-82,z:cz+82}];const p={model,path,next:(i+1)%4,x:path[i%4].x,z:path[i%4].z};scene.add(model);pedestrians.push(p);}
const guards=[{x:320,z:245,yaw:0},{x:350,z:255,yaw:Math.PI}].map(p=>{const model=createPerson('#3b5258');scene.add(model);const cone=new THREE.Mesh(new THREE.ConeGeometry(16,37,24,1,true),new THREE.MeshBasicMaterial({color:'#dca45a',transparent:true,opacity:.13,depthWrite:false,side:THREE.DoubleSide}));cone.rotation.x=Math.PI/2;cone.position.z=18;cone.position.y=.22;const group=new THREE.Group();group.add(cone);scene.add(group);return {...p,baseX:p.x,baseZ:p.z,model,cone:group};});
const tapeMeshes=new Map();for(const item of TAPES){const g=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color:'#e9bd6f',emissive:'#d39638',emissiveIntensity:.25,metalness:.3,roughness:.4});const body=new THREE.Mesh(new THREE.BoxGeometry(1.4,.8,.25),mat);g.add(body);for(const x of [-.38,.38]){const reel=new THREE.Mesh(new THREE.TorusGeometry(.2,.05,6,14),new THREE.MeshBasicMaterial({color:'#243b37'}));reel.position.set(x,.05,.14);g.add(reel);}g.position.set(item.x,1.3,item.z);g.visible=!saved.tapes.includes(item.id);scene.add(g);tapeMeshes.set(item.id,g);}
const targetGroup=new THREE.Group();const targetRing=new THREE.Mesh(new THREE.TorusGeometry(3.4,.22,8,48),new THREE.MeshBasicMaterial({color:'#f4b267'}));targetRing.rotation.x=-Math.PI/2;targetRing.position.y=.15;targetGroup.add(targetRing);const beacon=new THREE.Mesh(new THREE.CylinderGeometry(.55,.55,10,10,1,true),new THREE.MeshBasicMaterial({color:'#efaf65',transparent:true,opacity:.32,depthWrite:false}));beacon.position.y=5;targetGroup.add(beacon);scene.add(targetGroup);targetGroup.visible=false;
const routeLine=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#ebaa69',transparent:true,opacity:.8}));scene.add(routeLine);
const roadArrows=[];for(let i=0;i<14;i++){const arrow=new THREE.Mesh(new THREE.ConeGeometry(.7,1.9,3),new THREE.MeshBasicMaterial({color:'#f5d4a0',transparent:true,opacity:.8}));arrow.rotation.x=Math.PI/2;scene.add(arrow);roadArrows.push(arrow);}
const rainCount=850,rainPositions=new Float32Array(rainCount*6);const rainGeo=new THREE.BufferGeometry();for(let i=0;i<rainCount;i++){const j=i*6;rainPositions[j]=(Math.random()-.5)*160;rainPositions[j+1]=Math.random()*65;rainPositions[j+2]=(Math.random()-.5)*160;rainPositions[j+3]=rainPositions[j]+.4;rainPositions[j+4]=rainPositions[j+1]-2.4;rainPositions[j+5]=rainPositions[j+2];}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));const rain=new THREE.LineSegments(rainGeo,new THREE.LineBasicMaterial({color:'#b5ccd4',transparent:true,opacity:.4}));scene.add(rain);
const starsPositions=new Float32Array(450*3);for(let i=0;i<450;i++){const a=Math.random()*Math.PI*2,b=Math.random()*Math.PI/2;starsPositions[i*3]=Math.cos(a)*Math.cos(b)*950;starsPositions[i*3+1]=Math.sin(b)*950;starsPositions[i*3+2]=Math.sin(a)*Math.cos(b)*950;}const starsGeometry=new THREE.BufferGeometry();starsGeometry.setAttribute('position',new THREE.BufferAttribute(starsPositions,3));const stars=new THREE.Points(starsGeometry,new THREE.PointsMaterial({color:'#dce7f2',size:1.6,fog:false}));scene.add(stars);
let running=false,overlay=null,helpReturn=null,selectedJob='handover',mapTab='jobs',mission=null,waypoint=null,route=[],wanted=0,suspicion=0,hiddenTime=0,radio=0,cameraMode=0,camYaw=0,camPitch=.28,manualCamera=0,elapsed=0,toastTimer=0,dialogueTimer=0,lastSave=0,lastUI=0,lastMap=0,lastRoute=0,carCrashCooldown=0,gameReady=false;
const keys=new Set(),stateWeather=['晴朗','雨夜','薄雾'],radioNames=['京城电台 FM 88.7','胡同留声 FM 91.2','夜航调频 FM 103.9','电台关闭'];
let audio=null,audioMaster=null,engine=null,engineGain=null,nextNote=0,noteIndex=0;
function initAudio(){if(audio)return;try{audio=new (window.AudioContext||window.webkitAudioContext)();audioMaster=audio.createGain();audioMaster.gain.value=saved.settings.sound?.22:0;audioMaster.connect(audio.destination);engine=audio.createOscillator();engine.type='sawtooth';engineGain=audio.createGain();engineGain.gain.value=0;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=260;engine.connect(filter);filter.connect(engineGain);engineGain.connect(audioMaster);engine.start();}catch{}}
function audioTick(){if(!audio)return;audioMaster.gain.setTargetAtTime(saved.settings.sound?.22:0,audio.currentTime,.1);engineGain.gain.setTargetAtTime(running&&!overlay&&activeVehicle?.04:0,audio.currentTime,.12);engine.frequency.setTargetAtTime(35+Math.abs(activeVehicle?.speed||0)*4,audio.currentTime,.1);if(!running||overlay||!saved.settings.sound||radio===3)return;if(audio.currentTime>nextNote){const notes=[[196,246.94,293.66,392,329.63,293.66,246.94,220],[220,261.63,329.63,440,392,329.63,261.63,196],[146.83,220,293.66,349.23,293.66,220,174.61,220]][radio];const osc=audio.createOscillator(),gain=audio.createGain();osc.type=radio===1?'sine':'triangle';osc.frequency.value=notes[noteIndex++%8];gain.gain.setValueAtTime(0,audio.currentTime);gain.gain.linearRampToValueAtTime(.055,audio.currentTime+.03);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.65);osc.connect(gain);gain.connect(audioMaster);osc.start();osc.stop(audio.currentTime+.7);nextNote=audio.currentTime+(radio===2?.32:.47);}}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=4.2;}
function say(text,speaker='老陈 · 京城电台'){ $('#radio-name').textContent=speaker;$('#radio-message').textContent=text;dialogueTimer=9;}
function save(){saved.position={x:player.x,z:player.z};try{localStorage.setItem(STORE,JSON.stringify(saved));storageAvailable=true;$('#save-state').textContent='已保存到此浏览器';}catch{storageAvailable=false;$('#save-state').textContent='本地保存不可用，请在暂停菜单导出存档';}}
function applyQuality(){const q=saved.settings.quality;renderer.setPixelRatio(Math.min(devicePixelRatio,q==='high'?2:q==='low'?1:1.5));renderer.setSize(innerWidth,innerHeight,false);renderer.shadowMap.enabled=q!=='low';sun.shadow.mapSize.set(q==='high'?2048:1024,q==='high'?2048:1024);if(sun.shadow.map){sun.shadow.map.dispose();sun.shadow.map=null;}camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();$('#quality').value=q;}
function applySettings(){applyQuality();$('#sensitivity').value=saved.settings.sensitivity;$('#sensitivity-value').textContent=saved.settings.sensitivity+'%';$('#touch-setting').value=saved.settings.touch;$('#vibration').checked=saved.settings.vibration;const on=saved.settings.touch==='on'||saved.settings.touch==='auto'&&matchMedia('(pointer:coarse)').matches;document.body.classList.toggle('touch-on',on);$('#touch-controls').hidden=!on||!running||!!overlay;for(const id of ['home-sound','sound-setting'])$('#'+id).textContent=saved.settings.sound?'声音开启':'声音关闭';}
function releaseMouse(){if(document.pointerLockElement===canvas)document.exitPointerLock();keys.clear();}
function openPanel(name){releaseMouse();overlay=name;document.body.classList.add('panel-open');for(const el of document.querySelectorAll('.overlay'))el.hidden=el.id!==name+'-panel';$('#touch-controls').hidden=true;if(name==='map')renderMapList();if(name==='garage')renderGarage();if(name==='pause')applySettings();}
function closePanel(){const was=overlay;overlay=null;for(const el of document.querySelectorAll('.overlay'))el.hidden=true;document.body.classList.remove('panel-open');if(was==='help'&&helpReturn){const next=helpReturn;helpReturn=null;openPanel(next);return;}applySettings();canvas.focus();}
function start(mode){if(!gameReady)return;initAudio();audio?.resume();running=true;$('#home').hidden=true;$('#hud').hidden=false;closePanel();cameraMode=0;camYaw=0;camPitch=.25;applySettings();if(mode==='stealth'){safePlace(218,215);startJob('stealth');}else if(mode==='ferry'){safePlace(-207,-292);startJob('ferry');}else if(mode==='story'){const next=JOBS.slice(0,5).find(j=>!saved.completed.includes(j.id));if(next)startJob(next.id);else{waypoint={x:-18,z:35,label:'回到前门电台'};say('五段城市故事已经完成。回到前门，或继续寻找街巷里的十二盘磁带。');}}else say('车就在身边，按E上车。M打开地图，挑一件想做的事。');save();}
function safePlace(x=-18,z=35){if(activeVehicle){activeVehicle.speed=0;activeVehicle=null;}player.x=x;player.z=z;player.yaw=Math.PI;wanted=0;suspicion=0;player.crouch=false;camYaw=0;}
function startJob(id){const job=JOBS.find(j=>j.id===id);if(!job)return;mission={id,index:0,time:job.limit,total:job.limit,alerted:false};if(id==='stealth'){saved.hour=22.1;saved.weather=1;}if(id==='ferry')saved.hour=18.1;waypoint=null;closePanel();say(job.brief);toast('已接取：'+job.name);updateRoute();}
function finishJob(){const {job,reward}=settleJob(saved,mission);mission=null;wanted=Math.min(wanted,.6);save();toast(`${job.name}完成 · +¥${reward}`);say(saved.completed.length>=5?'五段旅程都完成了。北京的夜还长，随时回来继续漫游。':'收到，干得漂亮。打开地图，还能接到新的差事。');if(saved.settings.vibration)navigator.vibrate?.([35,40,35]);updateRoute();renderMapList();}
function advanceMission(){const job=JOBS.find(j=>j.id===mission?.id);if(!job)return;const stage=job.stages[mission.index];if(stage.foot&&activeVehicle){toast('停稳并下车后再交互。');return;}if(job.id==='echo'&&mission.index===1&&wanted>.2){toast('先离开巡逻视线，等警戒消退后再交付。');return;}if(job.id==='echo'&&mission.index===0){wanted=1.4;policeCars[1].x=-200;policeCars[1].z=-200;hiddenTime=0;say('巡逻车发现了你。利用街角甩开它们，再回前门。');}mission.index++;if(mission.index>=job.stages.length){finishJob();return;}toast('阶段完成 · '+job.stages[mission.index].label);if(job.id==='stealth')say('慢一点，按Q蹲行，别进入巡逻人员面前的灯光范围。');updateRoute();}
function failJob(message){const name=JOBS.find(j=>j.id===mission?.id)?.name;mission=null;toast((name?name+'：':'')+message);say('可以在地图中重新接取差事。进度与已有奖励都保留。');updateRoute();}
function getTarget(){if(mission){const j=JOBS.find(j=>j.id===mission.id);return {...j.stages[mission.index],mission:true};}return waypoint;}
function updateRoute(){const target=getTarget();route=target?makeRoute({x:player.x,z:player.z},target,ROADS,!!activeVehicle?.boat):[];routeLine.geometry.dispose();routeLine.geometry=new THREE.BufferGeometry().setFromPoints(route.map(p=>new THREE.Vector3(p.x,.2,p.z)));targetGroup.visible=!!target;if(target){targetGroup.position.set(target.x,0,target.z);}for(const arrow of roadArrows)arrow.visible=false;if(!target)return;let index=0;for(let i=1;i<route.length&&index<roadArrows.length;i++){const a=route[i-1],b=route[i],length=distance(a,b);for(let d=12;d<length&&index<roadArrows.length;d+=22){const f=d/length,arrow=roadArrows[index++];arrow.visible=true;arrow.position.set(a.x+(b.x-a.x)*f,.25,a.z+(b.z-a.z)*f);arrow.rotation.set(Math.PI/2,0,-Math.atan2(b.x-a.x,b.z-a.z));}}}
function nearestInteraction(){
 const target=getTarget();if(target?.mission&&!target.auto&&distance(player,target)<13)return {kind:'mission',label:target.action+' · '+target.label};
 const tape=TAPES.find(t=>!saved.tapes.includes(t.id)&&distance(player,t)<4);if(tape&&!activeVehicle)return {kind:'tape',item:tape,label:'收集磁带 · '+tape.name};
 if(distance(player,{x:-218,z:110})<17)return {kind:'garage',label:'进入前门车坊 · 换色与调校'};
 if(activeVehicle)return {kind:'exit',label:activeVehicle.boat?'靠岸后下船':'下车 · '+activeVehicle.name};
 const near=vehicles.filter(v=>distance(player,v)<(v.boat?22:6)).sort((a,b)=>distance(a,player)-distance(b,player))[0];if(near)return {kind:'enter',item:near,label:(near.boat?'上船':'上车')+' · '+near.name};
 return null;
}
function interact(){if(!running||overlay)return;const i=nearestInteraction();if(!i){toast('靠近车辆、目标或发光磁带后按E。');return;}if(i.kind==='mission'){advanceMission();return;}if(i.kind==='garage'){openPanel('garage');return;}if(i.kind==='tape'){saved.tapes.push(i.item.id);saved.cash+=45;tapeMeshes.get(i.item.id).visible=false;toast('已收集《'+i.item.name+'》 · +¥45');save();return;}if(i.kind==='enter'){if(Math.abs(i.item.speed)>5){toast('等车辆慢下来再上车。');return;}activeVehicle=i.item;activeVehicle.speed=0;player.crouch=false;player.x=i.item.x;player.z=i.item.z;camYaw=i.item.yaw+Math.PI;if(traffic.includes(i.item)){wanted=Math.max(wanted,1);say('街头车辆引起了巡逻注意。离开视线后警戒会慢慢消退。');}else say(i.item.boat?'WASD操船，空格制动。驶近岸边、停稳后按E离船。':'WASD驾驶，Shift氮气加速，空格手刹。R切换电台。');return;}if(i.kind==='exit'){const v=activeVehicle;if(Math.abs(v.speed)>4){toast('先减速停稳再离开。');return;}if(v.boat){const bank={x:-207,z:clamp(v.z,water.minZ+10,water.maxZ-10)};if(v.x<water.maxX-16){toast('请先驶回什刹海东岸码头。');return;}player.x=bank.x;player.z=bank.z;}else{const sides=[{x:v.x+Math.cos(v.yaw)*3,z:v.z-Math.sin(v.yaw)*3},{x:v.x-Math.cos(v.yaw)*3,z:v.z+Math.sin(v.yaw)*3}];const p=sides.find(p=>!blocked(p,world.colliders)&&!inWater(p,water));if(!p){toast('车门旁空间不足，请换个位置停车。');return;}Object.assign(player,p);}v.speed=0;activeVehicle=null;save();}}
function renderMapList(){const list=$('#map-list');list.replaceChildren();for(const b of document.querySelectorAll('[data-map-tab]'))b.classList.toggle('active',b.dataset.mapTab===mapTab);if(mapTab==='jobs'){for(const job of JOBS){const b=document.createElement('button');b.dataset.job=job.id;b.classList.toggle('selected',selectedJob===job.id);b.innerHTML=`<b>${saved.completed.includes(job.id)?'✓ ':''}${job.name}</b><small>${job.type} · ${job.area}</small>`;list.append(b);}const j=JOBS.find(j=>j.id===selectedJob);$('#job-detail').innerHTML=`<p>${j.brief}</p><small>报酬 ¥${j.reward} · 时限 ${j.limit} 秒</small><button data-accept="${j.id}">${mission?'切换到这项差事':'接取差事'}</button>`;}else{for(const l of world.landmarks){const b=document.createElement('button');b.dataset.place=l.id;b.innerHTML=`<b>${l.name}</b><small>${l.description||'北京主题地标'}</small>`;list.append(b);}const b=document.createElement('button');b.dataset.place='garage';b.innerHTML='<b>前门车坊</b><small>车辆配色与三级动力调校</small>';list.append(b);$('#job-detail').innerHTML='<p>选择地标设置导航；也可以点击地图中的任意位置。地图为游戏创作场景，不能用于现实出行。</p>';}
 $('#collection-status').textContent=`故事 ${saved.completed.length}/5 · 磁带 ${saved.tapes.length}/12 · 已配送 ${saved.delivered} 单`+(saved.bestRace?` · 最佳竞速 ${saved.bestRace.toFixed(1)} 秒`:'');}
function renderGarage(){const list=$('#paint-list');list.innerHTML=PAINTS.map((p,i)=>`<button data-paint="${i}"><i style="background:${p.value}"></i><span>${p.name}</span><small>${saved.paint===i?'当前涂装':p.price?'¥'+p.price:'免费'}</small></button>`).join('');$('#upgrade-info').textContent=`当前 ${saved.upgrade} / 3 级 · 加速、极速与氮气恢复提升`;$('#upgrade-button').textContent=saved.upgrade>=3?'已满级':`升级 · ¥${UPGRADES[saved.upgrade]}`;$('#upgrade-button').disabled=saved.upgrade>=3;}
function buyPaint(i){if(!Number.isInteger(i)||!PAINTS[i]||saved.paint===i)return;const p=PAINTS[i];if(saved.cash<p.price){toast('现金不足，完成差事或收集磁带可获得现金。');return;}saved.cash-=p.price;saved.paint=i;for(const m of ownCar.model.userData.bodyMaterials||[])m.color.set(p.value);save();renderGarage();toast('新涂装已应用：'+p.name);}
function buyUpgrade(){const price=UPGRADES[saved.upgrade];if(!price)return;if(saved.cash<price){toast('升级需要¥'+price+'，可以先去接一单差事。');return;}saved.cash-=price;saved.upgrade++;save();renderGarage();toast('动力升级完成 · '+saved.upgrade+'级');}
function setWaypoint(p,label){if(mission){toast('请先在暂停菜单取消当前差事，再设置自由导航。');return;}if(inWater(p,water)&&!activeVehicle?.boat){toast('水域请从什刹海东岸码头上船后探索。');return;}waypoint={x:clamp(p.x,-460,460),z:clamp(p.z,-460,460),label:label||'自选目的地'};closePanel();updateRoute();say('导航已设定：'+waypoint.label,'城市导航');}
function downloadSave(){save();const blob=new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='京城夜行-存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出。');}
function importSave(file){if(!file)return;if(file.size>1024*1024){toast('存档文件过大。');return;}file.text().then(text=>{const incoming=validateSave(JSON.parse(text));try{localStorage.setItem(STORE+'.previous',JSON.stringify(saved));}catch{}saved=incoming;mission=null;waypoint=null;safePlace(saved.position.x,saved.position.z);if(blocked(player,world.colliders)||inWater(player,water))safePlace();for(const [id,g] of tapeMeshes)g.visible=!saved.tapes.includes(id);for(const m of ownCar.model.userData.bodyMaterials||[])m.color.set(PAINTS[saved.paint].value);applySettings();save();toast('存档已导入，继续你的北京之旅。');}).catch(()=>toast('无法读取存档，请选择本系统导出的有效JSON文件。'));}
function handleAction(action){if(action==='interact')return interact();if(action==='crouch'){if(!activeVehicle)player.crouch=!player.crouch;return;}if(action==='help'){helpReturn=overlay==='pause'?'pause':null;openPanel('help');return;}if(action==='close'){closePanel();return;}if(action==='map'){if(overlay==='map')closePanel();else if(running)openPanel('map');return;}if(action==='pause'){if(overlay)closePanel();else openPanel('pause');return;}if(action==='sound'){initAudio();audio?.resume();saved.settings.sound=!saved.settings.sound;applySettings();save();return;}if(action==='day'){saved.hour=saved.hour>=20||saved.hour<6?8:saved.hour<15?17.4:22.1;toast('时间已切换：'+formatHour(saved.hour));save();return;}if(action==='weather'){saved.weather=(saved.weather+1)%3;toast('天气：'+stateWeather[saved.weather]);save();return;}if(action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('当前窗口不支持全屏。'));return;}if(action==='home'){save();running=false;mission=null;waypoint=null;closePanel();$('#hud').hidden=true;$('#home').hidden=false;applySettings();return;}if(action==='safe'){safePlace();closePanel();save();toast('已返回前门安全位置。');return;}if(action==='retry'){const id=mission?.id;if(id)startJob(id);else toast('目前没有进行中的差事。');return;}if(action==='cancel-job'){mission=null;waypoint=null;closePanel();updateRoute();toast('已取消差事，继续自由漫游。');return;}if(action==='clear-nav'){waypoint=null;updateRoute();toast('自由导航已清除。');return;}if(action==='export')return downloadSave();if(action==='import')return $('#save-file').click();if(action==='upgrade')return buyUpgrade();}
document.addEventListener('click',event=>{const e=event.target.closest('button');if(!e)return;if(e.dataset.start)return start(e.dataset.start);if(e.dataset.action)return handleAction(e.dataset.action);if(e.dataset.mapTab){mapTab=e.dataset.mapTab;renderMapList();return;}if(e.dataset.job){selectedJob=e.dataset.job;renderMapList();return;}if(e.dataset.accept)return startJob(e.dataset.accept);if(e.dataset.place){const p=e.dataset.place==='garage'?{x:-218,z:110,name:'前门车坊'}:world.landmarks.find(l=>l.id===e.dataset.place);return setWaypoint(p,p.name);}if(e.dataset.paint!==undefined)return buyPaint(Number(e.dataset.paint));});
$('#quality').addEventListener('change',e=>{saved.settings.quality=e.target.value;applyQuality();save();});$('#sensitivity').addEventListener('input',e=>{saved.settings.sensitivity=Number(e.target.value);$('#sensitivity-value').textContent=e.target.value+'%';save();});$('#touch-setting').addEventListener('change',e=>{saved.settings.touch=e.target.value;applySettings();save();});$('#vibration').addEventListener('change',e=>{saved.settings.vibration=e.target.checked;save();});$('#save-file').addEventListener('change',e=>{importSave(e.target.files[0]);e.target.value='';});
$('#big-map').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();setWaypoint({x:(e.clientX-r.left)/r.width*1040-520,z:(e.clientY-r.top)/r.height*1040-520});});
const keyAliases={ArrowUp:'KeyW',ArrowLeft:'KeyA',ArrowDown:'KeyS',ArrowRight:'KeyD',ShiftRight:'ShiftLeft'};
addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const code=keyAliases[e.code]||e.code;if(['KeyW','KeyA','KeyS','KeyD','Space','ShiftLeft','Escape','Tab'].includes(code))e.preventDefault();if(code==='Escape'){if(overlay)closePanel();else if(running)openPanel('pause');return;}if(e.repeat){keys.add(code);return;}if(code==='KeyM'&&running){handleAction('map');return;}if(code==='F2'&&running){e.preventDefault();openPanel('pause');return;}if(overlay)return;if(!running){if(code==='Enter')start('story');return;}keys.add(code);if(code==='KeyE')interact();if(code==='KeyQ'&&!activeVehicle)player.crouch=!player.crouch;if(code==='KeyC'){cameraMode=(cameraMode+1)%3;toast(['跟随机位','第一人称','俯视机位'][cameraMode]);}if(code==='KeyN')handleAction('day');if(code==='KeyX')handleAction('weather');if(code==='KeyR'){initAudio();radio=(radio+1)%4;say(radio===3?'只留发动机与城市的声音。':'正在播放原创合成旋律。',radioNames[radio]);}});
addEventListener('keyup',e=>keys.delete(keyAliases[e.code]||e.code));addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!overlay)openPanel('pause');});
let dragging=false,dragDistance=0,lastPointer={x:0,y:0};canvas.addEventListener('pointerdown',e=>{if(!running||overlay)return;dragging=true;dragDistance=0;lastPointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture?.(e.pointerId);});canvas.addEventListener('pointerup',()=>{if(dragDistance<3&&running&&!overlay&&!matchMedia('(pointer:coarse)').matches)canvas.requestPointerLock?.()?.catch?.(()=>{});dragging=false;});addEventListener('pointermove',e=>{if(!running||overlay)return;const locked=document.pointerLockElement===canvas;if(!locked&&!dragging)return;const dx=locked?e.movementX:e.clientX-lastPointer.x,dy=locked?e.movementY:e.clientY-lastPointer.y;lastPointer={x:e.clientX,y:e.clientY};dragDistance+=Math.abs(dx)+Math.abs(dy);camYaw-=dx*.004*saved.settings.sensitivity/100;camPitch=clamp(camPitch+dy*.0025*saved.settings.sensitivity/100,-.1,.9);manualCamera=4;});
for(const button of document.querySelectorAll('[data-key]')){button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keys.add(button.dataset.key);});const clear=()=>keys.delete(button.dataset.key);button.addEventListener('pointerup',clear);button.addEventListener('pointercancel',clear);button.addEventListener('lostpointercapture',clear);}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight,false);});addEventListener('beforeunload',save);
function tryMove(obj,x,z,radius){if(Math.abs(x)>478||Math.abs(z)>478)return false;const target={x,z};if(inWater(target,water)||blocked(target,world.colliders,radius))return false;obj.x=x;obj.z=z;return true;}
function stepPlayer(dt){const throttle=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),steer=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),boosting=keys.has('ShiftLeft');if(activeVehicle){const v=activeVehicle,up=v.owned?saved.upgrade:0;const accelerating=boosting&&v.boost>1&&throttle>0;const max=v.boat?14:42+up*5;v.speed+=throttle*(v.boat?8:19+up*3)*dt*(accelerating?1.7:1);if(!throttle)v.speed*=Math.exp(-dt*(v.boat?.7:.4));v.speed=clamp(v.speed,-(v.boat?5:12),max*(accelerating?1.35:1));if(keys.has('Space'))v.speed*=Math.exp(-dt*5);v.boost=clamp(v.boost+dt*(accelerating?-24:7+up*2),0,100);v.yaw-=steer*dt*(v.boat?.9:1.3)*clamp(Math.abs(v.speed)/8,0,1)*Math.sign(v.speed||1);const nx=v.x+Math.sin(v.yaw)*v.speed*dt,nz=v.z+Math.cos(v.yaw)*v.speed*dt;if(v.boat){v.x=clamp(nx,water.minX+4,water.maxX-5);v.z=clamp(nz,water.minZ+5,water.maxZ-5);if(v.x!==nx||v.z!==nz)v.speed*=.8;}else if(!tryMove(v,nx,nz,1.5)){if(Math.abs(v.speed)>12&&carCrashCooldown<=0){wanted=Math.max(wanted,.75);toast('路口注意减速，空格可制动。');carCrashCooldown=4;}v.speed*=-.22;}player.x=v.x;player.z=v.z;player.yaw=v.yaw;player.speed=v.speed;for(const wheel of v.model.userData.wheels||[])wheel.rotation.x+=v.speed*dt*1.7;if(v.model.userData.propeller)v.model.userData.propeller.rotation.z+=dt*(3+Math.abs(v.speed)*2);if(manualCamera<=0&&cameraMode!==1)camYaw+=angleDelta(v.yaw+Math.PI,camYaw)*Math.min(dt*3,1);}else{let dx=-Math.sin(camYaw)*throttle+Math.cos(camYaw)*steer,dz=-Math.cos(camYaw)*throttle-Math.sin(camYaw)*steer;const magnitude=Math.hypot(dx,dz),speed=player.crouch?2.8:boosting?10:5.4;player.speed=magnitude?speed:0;if(magnitude){dx=dx/magnitude*speed*dt;dz=dz/magnitude*speed*dt;tryMove(player,player.x+dx,player.z,.65);tryMove(player,player.x,player.z+dz,.65);const facing=Math.atan2(dx,dz);player.yaw+=angleDelta(facing,player.yaw)*Math.min(dt*12,1);}animatePerson(character,elapsed,player.speed,player.crouch);}}
function followPath(v,path,dt,speed){const p=path[v.next],d=distance(v,p);if(d<2){v.next=(v.next+1)%path.length;return;}const heading=Math.atan2(p.x-v.x,p.z-v.z);if(!Number.isFinite(v.yaw))v.yaw=heading;v.yaw+=angleDelta(heading,v.yaw)*Math.min(dt*5,1);v.speed=speed;v.x+=(p.x-v.x)/d*Math.min(d,speed*dt);v.z+=(p.z-v.z)/d*Math.min(d,speed*dt);}
function stepAmbient(dt){for(const v of traffic){if(v===activeVehicle)continue;const dest=v.path[v.next],nearJunction=distance(v,dest)<22;const red=Math.floor(elapsed/12)%2===(Math.abs(dest.x-v.x)>Math.abs(dest.z-v.z)?0:1);followPath(v,v.path,dt,nearJunction&&red?1:v.cruise);if(activeVehicle&&!activeVehicle.boat&&distance(player,v)<2.8&&Math.abs(activeVehicle.speed)>6&&carCrashCooldown<=0){activeVehicle.speed*=-.18;wanted=clamp(wanted+.9,0,3);carCrashCooldown=4;}}for(const p of pedestrians){followPath(p,p.path,dt,1.4);p.model.position.set(p.x,0,p.z);p.model.rotation.y=p.yaw;animatePerson(p.model,elapsed,1.4,false);}let seen=false;for(let i=0;i<policeCars.length;i++){const v=policeCars[i];if(v===activeVehicle)continue;if(wanted>.2&&distance(v,player)<210){const path=makeRoute(v,player);const next=path.find(p=>distance(v,p)>8)||player;const d=distance(v,next);const a=Math.atan2(next.x-v.x,next.z-v.z);v.yaw+=angleDelta(a,v.yaw)*Math.min(dt*3,1);v.speed=15+wanted*3;if(d>1){tryMove(v,v.x+Math.sin(v.yaw)*v.speed*dt,v.z+Math.cos(v.yaw)*v.speed*dt,1.3);}if(distance(v,player)<95)seen=true;if(distance(v,player)<5&&(!activeVehicle||Math.abs(activeVehicle.speed)<3)&&wanted>1){saved.cash=Math.max(0,saved.cash-Math.min(saved.cash,100));safePlace();if(mission)failJob('被巡逻拦下，差事中止。');toast('被巡逻拦下 · 已返回前门，扣除最多¥100');save();}}else{v.speed=0;}for(const b of v.model.userData.beacons||[]){b.visible=wanted>.2&&Math.sin(elapsed*12+i)>0;}}if(wanted>0){if(seen){hiddenTime=0;}else hiddenTime+=dt;if(hiddenTime>4)wanted=Math.max(0,wanted-dt*.065);}for(const v of vehicles){v.model.position.set(v.x,v.boat?water.y+Math.sin(elapsed*1.8)*.12:0,v.z);v.model.rotation.y=v.yaw;if(v.boat)v.model.rotation.z=Math.sin(elapsed*1.3)*.022;}
 let detection=false;for(let i=0;i<guards.length;i++){const g=guards[i];g.x=g.baseX+Math.sin(elapsed*.25+i*3)*12;g.z=g.baseZ+Math.cos(elapsed*.25+i*3)*10;g.yaw=elapsed*.25+i*3+Math.PI/2;g.model.position.set(g.x,0,g.z);g.model.rotation.y=g.yaw;g.cone.position.set(g.x,.12,g.z);g.cone.rotation.y=g.yaw;g.cone.visible=mission?.id==='stealth';animatePerson(g.model,elapsed,1.5,false);if(mission?.id!=='stealth'||activeVehicle)continue;const d=distance(g,player),a=Math.atan2(player.x-g.x,player.z-g.z),inCone=Math.abs(angleDelta(a,g.yaw))<.65;let occluded=false;for(let t=.15;t<1;t+=.15){if(blocked({x:g.x+(player.x-g.x)*t,z:g.z+(player.z-g.z)*t},world.colliders,.05)){occluded=true;break;}}if(!occluded&&d<(player.crouch?15:34)&&inCone||d<8&&player.speed>7)detection=true;}
 suspicion=clamp(suspicion+dt*(detection?24:-11),0,100);if(suspicion>=100&&mission?.id==='stealth'){mission.alerted=true;wanted=Math.max(wanted,1.2);suspicion=55;say('巡逻发现了动静！带上录音迅速撤离，奖励会有所减少。');}}
function stepMission(dt){if(!mission)return;mission.time-=dt;if(mission.time<=0){failJob('时间已用完，可以重新接取。');return;}const j=JOBS.find(j=>j.id===mission.id),s=j.stages[mission.index];if(s.auto&&distance(player,s)<(s.boat?17:16)&&(!s.boat||activeVehicle?.boat)&&(!s.stop||Math.abs(activeVehicle?.speed||0)<4)&&(j.id!=='race'||activeVehicle&&!activeVehicle.boat))advanceMission();}
function formatHour(hour){return `${String(Math.floor(hour)%24).padStart(2,'0')}:${String(Math.floor((hour%1)*60+1e-7)).padStart(2,'0')}`;}
function lighting(dt){const hour=running?saved.hour:17.4,night=hour>=20||hour<5,twilight=hour>=16&&hour<20;const colors=night?['#081725','#344048']:twilight?['#567789','#e9b987']:['#759cba','#c7d9d6'];sky.material.uniforms.top.value.lerp(new THREE.Color(colors[0]),Math.min(dt*2,1));sky.material.uniforms.bottom.value.lerp(new THREE.Color(colors[1]),Math.min(dt*2,1));scene.fog.color.lerp(new THREE.Color(saved.weather===2?'#a6ada5':night?'#182b35':saved.weather===1?'#737d7c':colors[1]),Math.min(dt*2,1));scene.fog.density=saved.weather===2?.004:saved.weather===1?.0023:.0011;hemi.intensity=night?.75:saved.weather===1?1.3:1.8;sun.intensity=night?.3:saved.weather===1?.7:2.6;sun.color.set(night?'#87aac4':twilight?'#ffd29b':'#fff2db');sun.position.set(player.x-180,night?250:twilight?130:320,player.z-230);sun.target.position.set(player.x,0,player.z);sunDisk.position.set(-450,night?550:twilight?110:450,-750);sunDisk.material.color.set(night?'#dfe8db':'#fff1ba');sunDisk.scale.setScalar(night?.55:1);stars.visible=night;rain.visible=saved.weather===1;if(rain.visible){rain.position.set(player.x,0,player.z);for(let i=0;i<rainCount;i++){const j=i*6;rainPositions[j+1]-=dt*33;if(rainPositions[j+1]<0)rainPositions[j+1]=65;rainPositions[j+4]=rainPositions[j+1]-2.4;}rainGeo.attributes.position.needsUpdate=true;}renderer.toneMappingExposure=night?1.35:1.1;for(const obj of world.animated||[]){if(obj.userData?.lightMaterial)obj.userData.lightMaterial.emissiveIntensity=night?1.8:.15;if(obj.userData?.waterMaterial)obj.material.opacity=.8;}for(const v of vehicles){for(const h of [...(v.model.userData.headlights||[]),...(v.model.userData.taillights||[])])if(h.material?.emissive)h.material.emissiveIntensity=night?2:.35;}}
function cameraTick(dt){if(!running){const a=elapsed*.022;camera.position.set(80+Math.sin(a)*150,125+Math.sin(a*.5)*18,120+Math.cos(a)*150);camera.lookAt(30,15,-110);return;}character.position.set(player.x,0,player.z);character.rotation.y=player.yaw;character.visible=!activeVehicle&&cameraMode!==1;const target=new THREE.Vector3(player.x,activeVehicle?.boat?1.5:activeVehicle?1.4:1.45,player.z),desired=new THREE.Vector3();if(cameraMode===1){const yaw=activeVehicle?activeVehicle.yaw:camYaw+Math.PI;desired.copy(target).add(new THREE.Vector3(Math.sin(yaw)*.5,.25,Math.cos(yaw)*.5));camera.position.lerp(desired,1-Math.exp(-dt*14));camera.lookAt(camera.position.x-Math.sin(camYaw)*30,camera.position.y-camPitch*14,camera.position.z-Math.cos(camYaw)*30);}else if(cameraMode===2){desired.set(player.x+1,85,player.z+34);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(target);}else{const dist=activeVehicle?activeVehicle.boat?13:11:7.8;let d=dist;for(let sample=2;sample<dist;sample+=1.2){const p={x:player.x+Math.sin(camYaw)*sample,z:player.z+Math.cos(camYaw)*sample};if(blocked(p,world.colliders,.2)){d=Math.max(2,sample-1);break;}}desired.set(player.x+Math.sin(camYaw)*d,target.y+2+camPitch*8,player.z+Math.cos(camYaw)*d);camera.position.lerp(desired,1-Math.exp(-dt*6));camera.lookAt(target.x,target.y+.5,target.z);} }
function drawMap(canvas,large){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#203c35';ctx.fillRect(0,0,w,h);const scale=large?w/1040:1.5,ox=large?w/2:w/2-player.x*scale,oz=large?h/2:h/2-player.z*scale;const point=p=>[ox+p.x*scale,oz+p.z*scale];ctx.save();ctx.translate(ox,oz);ctx.scale(scale,scale);ctx.fillStyle='#60715d';ctx.fillRect(-490,-490,980,980);for(const r of ROADS){ctx.fillStyle='#a3aa8c';ctx.fillRect(r-12,-490,24,980);ctx.fillRect(-490,r-12,980,24);ctx.strokeStyle='#d3d1aa77';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(r,-490);ctx.lineTo(r,490);ctx.moveTo(-490,r);ctx.lineTo(490,r);ctx.stroke();}for(const f of world.mapFeatures||[]){ctx.fillStyle=f.color||'#82917a';ctx.fillRect(f.x-f.w/2,f.z-f.d/2,f.w,f.d);}ctx.fillStyle='#305d5c';ctx.fillRect(water.minX,water.minZ,water.maxX-water.minX,water.maxZ-water.minZ);ctx.strokeStyle='#d78e5a';ctx.lineWidth=large?3:3;ctx.lineJoin='round';ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(p.x,p.z):ctx.moveTo(p.x,p.z));ctx.stroke();for(const t of TAPES){ctx.fillStyle=saved.tapes.includes(t.id)?'#b1b69c':'#f0d28c';ctx.save();ctx.translate(t.x,t.z);ctx.rotate(Math.PI/4);ctx.fillRect(-2.8,-2.8,5.6,5.6);ctx.restore();}ctx.fillStyle='#f2d6b1';ctx.strokeStyle='#25352c';ctx.lineWidth=2;ctx.strokeRect(-225,102,14,14);ctx.strokeRect(-230,-298,10,10);ctx.restore();if(large){ctx.font='bold 26px Microsoft YaHei';ctx.textAlign='center';ctx.textBaseline='middle';for(const l of world.landmarks){const [x,z]=point(l);ctx.strokeStyle='#1b3029';ctx.lineWidth=5;ctx.strokeText(l.name,x,z-12);ctx.fillStyle='#f2ead2';ctx.fillText(l.name,x,z-12);}}const target=getTarget();if(target){const [x,z]=point(target);ctx.strokeStyle='#f1ac75';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,z,large?10:10,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#e79962';ctx.beginPath();ctx.arc(x,z,4,0,Math.PI*2);ctx.fill();}const [x,z]=point(player);ctx.save();ctx.translate(x,z);ctx.rotate(-player.yaw+Math.PI);ctx.shadowColor='#102b21';ctx.shadowBlur=4;ctx.fillStyle='#fff1cc';ctx.strokeStyle='#172b22';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(8,9);ctx.lineTo(0,5);ctx.lineTo(-8,9);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();ctx.fillStyle='#e4dfc0';ctx.font='bold 13px monospace';ctx.textAlign='left';ctx.fillText('N',12,20);if(large){ctx.font='12px Microsoft YaHei';ctx.fillText('100 m  ━━━━━',w-145,h-16);}}
function uiTick(){const nearest=world.landmarks.reduce((a,b)=>distance(a,player)<distance(b,player)?a:b,world.landmarks[0]);$('#district').textContent=nearest?.name||'北京街区';$('#map-area').textContent=nearest?.name||'北京';$('#clock').textContent=formatHour(saved.hour);$('#weather-label').textContent=stateWeather[saved.weather];$('#cash').textContent='¥'+saved.cash.toLocaleString('zh-CN');$('#wanted').textContent=wanted>.15?'警戒 '+ '◆'.repeat(Math.ceil(wanted))+(hiddenTime>4?' · 正在消退':''):'自由漫游';$('#speed-panel').hidden=!activeVehicle;if(activeVehicle){$('#vehicle-name').textContent=activeVehicle.name;$('#speed').textContent=Math.round(Math.abs(activeVehicle.speed)*3.6);$('#boost').value=activeVehicle.boost;}const i=nearestInteraction();$('#interaction').hidden=!i||!!overlay;if(i)$('#interaction span').textContent=i.label;$('#mission-hud').hidden=!mission;if(mission){const j=JOBS.find(j=>j.id===mission.id);$('#mission-name').textContent=j.name;$('#mission-category').textContent=j.type;$('#mission-step').textContent=j.stages[mission.index].label;$('#mission-progress').textContent=`阶段 ${mission.index+1} / ${j.stages.length}`;$('#mission-timer').textContent=Math.ceil(mission.time)+' 秒';}const target=getTarget();$('#navigation').hidden=!target;if(target){const d=distance(player,target);$('#nav-distance').textContent=d>=1000?(d/1000).toFixed(1)+' km':Math.ceil(d)+' m';$('#nav-direction').textContent=d<15?target.auto?'通过标记区域':'已到达 · E交互':activeVehicle?.boat?'驶向水面标记':'沿道路前进';}$('#stealth-meter').hidden=mission?.id!=='stealth';$('#stealth-meter meter').value=suspicion;$('#stealth-meter span').textContent=player.crouch?'已蹲行':'Q 蹲行';if(waypoint&&distance(player,waypoint)<10){toast('已到达：'+waypoint.label);waypoint=null;updateRoute();}if(dialogueTimer<=0){$('#radio-name').textContent=radioNames[radio];$('#radio-message').textContent=player.crouch?'正在蹲行，脚步更轻。':activeVehicle?'沿街走走，下一段故事就在前面。':'按M查看地图与差事，靠近发光磁带可收集。';}}
applySettings();$('#load-state').textContent=storageAvailable?'场景准备就绪 · 全部资源本地加载':'场景准备就绪 · 存档不可用时请手动导出';$('#story-label').textContent=saved.completed.length?'继续故事':'开始故事';gameReady=true;
let previous=performance.now(),fpsStart=performance.now(),fpsFrames=0;function frame(now){fpsFrames++;if(now-fpsStart>1500){document.querySelector('#performance-info').textContent='实时帧率 '+Math.round(fpsFrames*1000/(now-fpsStart))+' FPS · 若画面卡顿，请切换流畅模式';fpsStart=now;fpsFrames=0;}const dt=Math.min((now-previous)/1000,.05);previous=now;elapsed+=dt;toastTimer-=dt;dialogueTimer-=dt;manualCamera-=dt;carCrashCooldown-=dt;if(toastTimer<=0)$('#toast').hidden=true;if(running&&!overlay){stepPlayer(dt);stepAmbient(dt);stepMission(dt);saved.hour=(saved.hour+dt*.002)%24;if(elapsed-lastSave>5){lastSave=elapsed;save();}if(elapsed-lastRoute>.6){lastRoute=elapsed;updateRoute();}}lighting(dt);cameraTick(dt);targetRing.rotation.z+=dt*.4;for(const [id,g] of tapeMeshes){g.rotation.y+=dt*.65;g.position.y=1.5+Math.sin(elapsed*2+TAPES.findIndex(t=>t.id===id))*.16;}if(elapsed-lastUI>.12){lastUI=elapsed;uiTick();}if(elapsed-lastMap>.16){lastMap=elapsed;if(running)drawMap($('#radar'),false);if(overlay==='map')drawMap($('#big-map'),true);}audioTick();renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
addEventListener('error',e=>{if(!gameReady){$('#fatal').hidden=false;$('#fatal p').textContent='场景资源加载失败：'+e.message;}});
